from core import *
import hashlib,csv
from PIL import Image
folder=ROOT/'human_simulation';folder.mkdir(exist_ok=True);(folder/'images').mkdir(exist_ok=True)
verified=set(json.load(open(ROOT/'data/egonormia/verified_split.json'))['split']);media=set(json.load(open(ROOT/'data/media_sample_ids.json')));candidates=sorted(verified&media,key=lambda k:hashlib.sha256(('human-20261004:'+k).encode()).hexdigest());selected=[];seen=set()
for k in candidates:
 if source(k) not in seen:selected.append(k);seen.add(source(k))
 if len(selected)==20:break
assert len(selected)==20
records=[];keys=[]
for n,k in enumerate(selected):
 v=D[k];im=Image.open(ROOT/'data/media'/(k+'.jpg'));contact=Image.new('RGB',(1200,1020),'white')
 for i in range(5):
  tile=im.crop((i*im.width//5,0,(i+1)*im.width//5,im.height));tile.thumbnail((600,340));contact.paste(tile,((i%2)*600,(i//2)*340))
 contact.save(folder/'images'/f'{n+1:02d}.jpg',quality=90)
 records.append(dict(id=k,options=[b if b else 'None of these actions is appropriate.' for b in v['behaviors']],description=v['desc'],image=f'images/{n+1:02d}.jpg'))
 keys.append({'item':k,'answer_index_1based':v['correct']+1})
pd.DataFrame(keys).to_csv(folder/'answer_key_do_not_open_before_annotation.csv',index=False)
html='''<!doctype html><html><head><meta charset="utf-8"><title>EgoNormia staged human annotation</title><style>body{font:17px/1.5 system-ui;max-width:1000px;margin:30px auto;padding:0 20px;color:#18323c}button,select,input,textarea{font:inherit;padding:9px;margin:7px 0}button{cursor:pointer}img{width:100%;height:auto}textarea{width:95%;height:80px}.card{background:#f4f7f8;padding:20px;border-radius:12px}.warn{color:#8e4717}label{display:block}</style></head><body><h1>Staged human annotation</h1><p>20 examples, three stages each: options only, then description, then frames. Choose the most appropriate next action; the fifth/empty choice is valid. Save each stage before seeing the next. Do not consult the answer key or discuss answers until every annotator finishes.</p><p class="warn">This is the reusable blank collection tool. Completed chat responses, when present, are in chat_session.json and responses_scored.csv. Confidence is self-reported, not a correctness score.</p><label>Anonymous annotator ID <input id="person" value="annotator1"></label><div class="card" id="card"></div><button onclick="save()">Save stage and continue</button> <button onclick="download()">Download responses CSV</button><p id="status"></p><script>const items=DATA;let index=0,stage=0,rows=[];const stages=['options','description','frames'];function show(){if(index>=items.length){document.getElementById('card').innerHTML='<h2>Finished</h2><p>Download your responses before closing.</p>';return}let q=items[index];document.getElementById('card').innerHTML=`<h2>Example ${index+1}/20 · ${stages[stage]}</h2><p>${q.id}</p>`+q.options.map((s,i)=>`<label><input type="radio" name="answer" value="${i+1}"> ${i+1}. ${esc(s)}</label>`).join('')+(stage>=1?`<h3>Description</h3><p>${esc(q.description).replaceAll('\\n','<br>')}</p>`:'')+(stage>=2?`<h3>Frames in temporal order</h3><img src="${q.image}">`:'')+`<label>Confidence <select id="confidence"><option value="">Choose 1 to 5</option>${[1,2,3,4,5].map(i=>`<option>${i}</option>`).join('')}</select></label><label>Evidence/cue used <textarea id="cue"></textarea></label><label>Cue type <select id="type"><option>option language</option><option>spatial configuration</option><option>object/action</option><option>gesture/interaction</option><option>temporal change</option><option>norm knowledge</option><option>uncertain</option></select></label>`}function esc(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}function save(){if(index>=items.length)return;let ans=document.querySelector('input[name=answer]:checked'),conf=document.getElementById('confidence').value;if(!ans||!conf){document.getElementById('status').textContent='Please choose an answer and confidence.';return}rows.push({annotator:document.getElementById('person').value,item:items[index].id,stage:stages[stage],answer:ans.value,confidence:conf,cue:document.getElementById('cue').value,cue_type:document.getElementById('type').value});document.getElementById('status').textContent=`${rows.length} stage responses saved in this tab. Download periodically.`;stage++;if(stage===3){stage=0;index++}show()}function download(){let fields=['annotator','item','stage','answer','confidence','cue','cue_type'];let quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';let s=fields.join(',')+'\\n'+rows.map(r=>fields.map(k=>quote(r[k])).join(',')).join('\\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type:'text/csv'}));a.download='human_responses.csv';a.click();URL.revokeObjectURL(a.href)}show()</script></body></html>'''.replace('DATA',json.dumps(records))
(folder/'annotation.html').write_text(html)
pd.DataFrame(columns=['annotator','item','stage','answer','confidence','cue','cue_type']).to_csv(folder/'responses_template.csv',index=False)
